#!/bin/bash
# Generated by OpenAI Codex on 2026-11-01. Run as root; briefly stops CATS only.
set -euo pipefail
[[ $(id -u) == 0 ]]
uid=$(id -u catsdeploy)
image=/var/lib/cats-storage/home.ext4
if mountpoint -q /home/catsdeploy; then
  findmnt /home/catsdeploy
  exit 0
fi
[[ ! -e $image ]] || { echo 'Existing storage image requires manual inspection'; exit 1; }
[[ $(df --output=avail -B1 / | tail -1) -gt 15000000000 ]]
install -d -m 700 /var/lib/cats-storage
fallocate -l 8G "$image"
chmod 600 "$image"
mkfs.ext4 -q -E nodiscard -m 0 "$image"
install -d -m 700 /mnt/cats-storage-migrate
mount -o loop,nodev,nosuid "$image" /mnt/cats-storage-migrate
# Stop the daemon cleanly before copying its volumes and container metadata.
runuser -u catsdeploy -- env XDG_RUNTIME_DIR="/run/user/$uid" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$uid/bus" systemctl --user stop docker
systemctl stop "user@$uid.service"
rsync -aHAX --numeric-ids /home/catsdeploy/ /mnt/cats-storage-migrate/
chown catsdeploy:catsdeploy /mnt/cats-storage-migrate
chmod 700 /mnt/cats-storage-migrate
umount /mnt/cats-storage-migrate
# Retain the original directory for rollback; make it root-only.
mv /home/catsdeploy /var/lib/cats-storage/original-home
chown root:root /var/lib/cats-storage/original-home
chmod 700 /var/lib/cats-storage/original-home
install -d -m 000 /home/catsdeploy
printf '%s\n' "$image /home/catsdeploy ext4 loop,nodev,nosuid 0 0" >> /etc/fstab
mount /home/catsdeploy
install -d -m 755 "/etc/systemd/system/user@$uid.service.d"
cat > "/etc/systemd/system/user@$uid.service.d/cats-storage.conf" <<'EOF'
[Unit]
RequiresMountsFor=/home/catsdeploy
EOF
systemctl daemon-reload
systemctl start "user@$uid.service"
runuser -u catsdeploy -- env XDG_RUNTIME_DIR="/run/user/$uid" DBUS_SESSION_BUS_ADDRESS="unix:path=/run/user/$uid/bus" systemctl --user start docker
findmnt /home/catsdeploy
